mapper.select:
SELECT r.id, r.title, r.description, r.file_type, r.file_size, r.download_count, r.upload_type, r.folder_name, r.relative_path, r.batch_no, r.create_time, COALESCE(u.nickname, u.username) AS uploaderName FROM resource r LEFT JOIN user u ON r.user_id = u.id
r.user_id = #{userId}
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%'))
AND r.file_type = #{fileType}
AND r.upload_type = #{uploadType}
ORDER BY r.create_time DESC, r.id DESC

select nickname
from user left join resource on user.id = resource.user_id
where resource.id = #{resId};
